import React, { useEffect, useState } from "react";
import { fetchAlerts, fetchBlockedIPs, blockIP, unblockIP, connectWs } from "../services/api";
import AlertsTable from "./AlertsTable";
import TrafficChart from "./TrafficChart";
import SeverityPieChart from "./SeverityPieChart";

export default function Dashboard() {
  const [alerts, setAlerts] = useState([]);
  const [blockedIPs, setBlockedIPs] = useState([]);
  const [severityFilter, setSeverityFilter] = useState("all");
  const [typeFilter, setTypeFilter] = useState("all");
  const [ipSearch, setIpSearch] = useState("");

  // initial load
  useEffect(() => {
    fetchAlerts()
      .then((data) => {
        if (Array.isArray(data)) setAlerts(data);
      })
      .catch((err) => console.error("Error fetching alerts:", err));

    fetchBlockedIPs()
      .then((data) => {
        if (Array.isArray(data)) setBlockedIPs(data);
      })
      .catch((err) => console.error("Error fetching blocked IPs:", err));
  }, []);

  // live updates
  useEffect(() => {
    const ws = connectWs((alert) => setAlerts((prev) => [alert, ...prev]));
    return () => ws.close();
  }, []);

  const handleBlockIP = async (ip) => {
    if (!ip) return;
    try {
      const res = await blockIP(ip);
      if (res && res.blocked_ips) setBlockedIPs(res.blocked_ips);
      else setBlockedIPs((prev) => [...prev, ip]);
    } catch (e) {
      console.error("Failed to block IP:", e);
    }
  };

  const handleUnblockIP = async (ip) => {
    if (!ip) return;
    try {
      const res = await unblockIP(ip);
      if (res && res.blocked_ips) setBlockedIPs(res.blocked_ips);
      else setBlockedIPs((prev) => prev.filter((item) => item !== ip));
    } catch (e) {
      console.error("Failed to unblock IP:", e);
    }
  };

  const exportCSV = () => {
    if (filteredAlerts.length === 0) return;
    const headers = ["ID", "Detected At", "Source IP", "Destination IP", "Attack Type", "Severity", "Detail"];
    const rows = filteredAlerts.map((a) => [
      a.id || "",
      `"${a.detected_at || ""}"`,
      `"${a.source_ip || ""}"`,
      `"${a.dest_ip || ""}"`,
      `"${a.type || ""}"`,
      `"${a.severity || ""}"`,
      `"${(a.detail || "").replace(/"/g, '""')}"`,
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), ...rows.map((e) => e.join(","))].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `NetShield_Alerts_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportJSON = () => {
    if (filteredAlerts.length === 0) return;
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(filteredAlerts, null, 2));
    const link = document.createElement("a");
    link.setAttribute("href", dataStr);
    link.setAttribute("download", `NetShield_Alerts_${new Date().toISOString().slice(0, 10)}.json`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Extract unique alert types dynamically
  const alertTypes = Array.from(new Set(alerts.map((a) => a.type).filter(Boolean)));

  const filteredAlerts = alerts.filter((a) => {
    // Severity filter
    if (severityFilter !== "all" && (a.severity || "").toLowerCase() !== severityFilter.toLowerCase()) {
      return false;
    }
    // Type filter
    if (typeFilter !== "all" && (a.type || "").toLowerCase() !== typeFilter.toLowerCase()) {
      return false;
    }
    // IP filter (source or destination match)
    if (ipSearch.trim()) {
      const query = ipSearch.trim().toLowerCase();
      const matchSrc = (a.source_ip || "").toLowerCase().includes(query);
      const matchDst = (a.dest_ip || "").toLowerCase().includes(query);
      if (!matchSrc && !matchDst) return false;
    }
    return true;
  });

  const highCount = alerts.filter(a => (a.severity || "").toLowerCase() === "high").length;
  const medCount = alerts.filter(a => (a.severity || "").toLowerCase() === "medium").length;
  const lowCount = alerts.filter(a => (a.severity || "").toLowerCase() === "low").length;

  return (
    <div style={{
      padding: "2rem",
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      backgroundColor: "#000000", // Pitch Black
      backgroundImage: "radial-gradient(circle at 15% 15%, rgba(0, 210, 255, 0.08) 0%, transparent 45%), radial-gradient(circle at 85% 85%, rgba(255, 123, 0, 0.06) 0%, transparent 50%)",
      color: "#e2e8f0",
      minHeight: "100vh"
    }}>
      {/* Header Bar */}
      <header style={{
        marginBottom: "1.5rem",
        borderBottom: "1px solid rgba(0, 210, 255, 0.15)",
        paddingBottom: "1.2rem",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        flexWrap: "wrap",
        gap: "1.2rem"
      }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: "0.6rem" }}>
            <span style={{ fontSize: "1.8rem" }}>🛡️</span>
            <h1 style={{
              margin: 0,
              fontSize: "1.8rem",
              fontWeight: "900",
              letterSpacing: "-0.5px",
              background: "linear-gradient(135deg, #ffffff 40%, #00d2ff 100%)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent"
            }}>
              NetShield SOC
            </h1>
            <span style={{
              background: "rgba(255, 123, 0, 0.15)",
              color: "#ff7b00",
              border: "1px solid rgba(255, 123, 0, 0.4)",
              borderRadius: "20px",
              padding: "0.2rem 0.6rem",
              fontSize: "0.75rem",
              fontWeight: "800",
              letterSpacing: "1px",
              textTransform: "uppercase"
            }}>
              SYSTEM ACTIVE
            </span>
          </div>
          <p style={{ margin: "0.4rem 0 0 0", color: "#718096", fontSize: "0.9rem" }}>
            Real-time Intrusion Detection, Automated Threat Diagnosis & Firewall Mitigation
          </p>
        </div>

        <div style={{ display: "flex", gap: "0.8rem" }}>
          <button
            onClick={exportCSV}
            title="Download current filtered diagnosis records as a CSV spreadsheet"
            style={{
              padding: "0.55rem 1.1rem",
              background: "rgba(0, 210, 255, 0.12)",
              color: "#00d2ff",
              border: "1px solid rgba(0, 210, 255, 0.4)",
              borderRadius: "6px",
              fontSize: "0.85rem",
              cursor: "pointer",
              fontWeight: "700",
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              transition: "all 0.2s",
              boxShadow: "0 0 15px rgba(0, 210, 255, 0.15)"
            }}
          >
            📥 Export CSV
          </button>
          <button
            onClick={exportJSON}
            title="Download current filtered diagnosis records as raw JSON"
            style={{
              padding: "0.55rem 1.1rem",
              background: "#080c14",
              color: "#e2e8f0",
              border: "1px solid rgba(255, 255, 255, 0.15)",
              borderRadius: "6px",
              fontSize: "0.85rem",
              cursor: "pointer",
              fontWeight: "600",
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              transition: "all 0.2s"
            }}
          >
            📋 Export JSON
          </button>
        </div>
      </header>

      {/* User Guide: Quick Diagnosis & Action Workflow */}
      <div style={{
        background: "linear-gradient(135deg, rgba(0, 210, 255, 0.05) 0%, rgba(6, 9, 17, 0.95) 100%)",
        border: "1px solid rgba(0, 210, 255, 0.25)",
        borderRadius: "10px",
        padding: "1.1rem 1.4rem",
        marginBottom: "1.8rem",
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))",
        gap: "1.2rem",
        boxShadow: "0 4px 18px rgba(0, 0, 0, 0.7)"
      }}>
        {/* Step 1 */}
        <div style={{ borderLeft: "3px solid #00d2ff", paddingLeft: "0.9rem" }}>
          <div style={{ fontSize: "0.75rem", color: "#00d2ff", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "800" }}>
            Step 1 • Diagnose Threats
          </div>
          <div style={{ fontSize: "0.9rem", color: "#e2e8f0", marginTop: "0.25rem", fontWeight: "600" }}>
            Identify Spikes & Classifications
          </div>
          <div style={{ fontSize: "0.8rem", color: "#718096", marginTop: "0.2rem", lineHeight: "1.3" }}>
            Check the <strong>Traffic Chart</strong> and <strong>Severity Donut</strong> to diagnose attack surges and proportions.
          </div>
        </div>

        {/* Step 2 */}
        <div style={{ borderLeft: "3px solid #ffa200", paddingLeft: "0.9rem" }}>
          <div style={{ fontSize: "0.75rem", color: "#ffa200", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "800" }}>
            Step 2 • Filter & Pinpoint
          </div>
          <div style={{ fontSize: "0.9rem", color: "#e2e8f0", marginTop: "0.25rem", fontWeight: "600" }}>
            Use the Investigation Toolbar
          </div>
          <div style={{ fontSize: "0.8rem", color: "#718096", marginTop: "0.2rem", lineHeight: "1.3" }}>
            Type suspect IPs in <strong>Search IP</strong> or filter by <strong>Attack Type</strong> / <strong>Severity</strong> in the stream below.
          </div>
        </div>

        {/* Step 3 */}
        <div style={{ borderLeft: "3px solid #ff7b00", paddingLeft: "0.9rem" }}>
          <div style={{ fontSize: "0.75rem", color: "#ff7b00", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "800" }}>
            Step 3 • Take Mitigation Action
          </div>
          <div style={{ fontSize: "0.9rem", color: "#e2e8f0", marginTop: "0.25rem", fontWeight: "600" }}>
            Block or Export Records
          </div>
          <div style={{ fontSize: "0.8rem", color: "#718096", marginTop: "0.2rem", lineHeight: "1.3" }}>
            Click <span style={{ color: "#ff7b00", fontWeight: "bold" }}>Block IP</span> to neutralize offending IPs, or export forensic incident logs above.
          </div>
        </div>
      </div>

      {/* Metrics Row */}
      <div style={{ display: "flex", gap: "1.2rem", marginBottom: "2rem", flexWrap: "wrap" }}>
        {/* Total */}
        <div style={{
          flex: "1 1 200px",
          background: "#060911", // Pitch dark container
          padding: "1.2rem",
          borderRadius: "10px",
          border: "1px solid rgba(0, 210, 255, 0.15)",
          boxShadow: "0 4px 20px rgba(0, 0, 0, 0.8)"
        }}>
          <div style={{ fontSize: "0.8rem", color: "#718096", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "600" }}>Total Threat Events</div>
          <div style={{ fontSize: "2rem", fontWeight: "800", color: "#f8fafc", marginTop: "0.2rem" }}>{alerts.length}</div>
        </div>

        {/* High Severity - Vivid Amber Orange Accent */}
        <div style={{
          flex: "1 1 200px",
          background: "linear-gradient(145deg, #190e03 0%, #060911 100%)",
          padding: "1.2rem",
          borderRadius: "10px",
          border: "1px solid rgba(255, 123, 0, 0.45)",
          boxShadow: "0 0 25px rgba(255, 123, 0, 0.18)"
        }}>
          <div style={{ fontSize: "0.8rem", color: "#ff7b00", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "800" }}>Critical Threats</div>
          <div style={{ fontSize: "2rem", fontWeight: "800", color: "#ff7b00", marginTop: "0.2rem" }}>{highCount}</div>
        </div>

        {/* Medium Severity - Golden Amber */}
        <div style={{
          flex: "1 1 200px",
          background: "linear-gradient(145deg, #171203 0%, #060911 100%)",
          padding: "1.2rem",
          borderRadius: "10px",
          border: "1px solid rgba(255, 162, 0, 0.35)",
          boxShadow: "0 0 20px rgba(255, 162, 0, 0.12)"
        }}>
          <div style={{ fontSize: "0.8rem", color: "#ffa200", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "700" }}>Suspicious Activity</div>
          <div style={{ fontSize: "2rem", fontWeight: "800", color: "#ffa200", marginTop: "0.2rem" }}>{medCount}</div>
        </div>

        {/* Low Severity - Arctic Blue */}
        <div style={{
          flex: "1 1 200px",
          background: "linear-gradient(145deg, #02141f 0%, #060911 100%)",
          padding: "1.2rem",
          borderRadius: "10px",
          border: "1px solid rgba(0, 210, 255, 0.35)",
          boxShadow: "0 0 20px rgba(0, 210, 255, 0.15)"
        }}>
          <div style={{ fontSize: "0.8rem", color: "#00d2ff", textTransform: "uppercase", letterSpacing: "1px", fontWeight: "700" }}>Routine Anomaly</div>
          <div style={{ fontSize: "2rem", fontWeight: "800", color: "#00d2ff", marginTop: "0.2rem" }}>{lowCount}</div>
        </div>
      </div>

      {/* Visualizations Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(400px, 1fr))", gap: "1.5rem", marginBottom: "2rem" }}>
        <div style={{
          background: "#060911",
          padding: "1.4rem",
          borderRadius: "10px",
          border: "1px solid rgba(0, 210, 255, 0.18)",
          boxShadow: "0 4px 20px rgba(0, 0, 0, 0.8)"
        }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
            <h2 style={{ fontSize: "1.05rem", margin: 0, color: "#f8fafc", fontWeight: "700" }}>Traffic Ingestion Flow (Events / Min)</h2>
            <span style={{ fontSize: "0.75rem", color: "#00d2ff", background: "rgba(0, 210, 255, 0.1)", border: "1px solid rgba(0, 210, 255, 0.3)", padding: "0.2rem 0.5rem", borderRadius: "4px" }}>ARCTIC FLOW</span>
          </div>
          <TrafficChart alerts={alerts} />
        </div>

        <div style={{
          background: "#060911",
          padding: "1.4rem",
          borderRadius: "10px",
          border: "1px solid rgba(0, 210, 255, 0.18)",
          boxShadow: "0 4px 20px rgba(0, 0, 0, 0.8)"
        }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
            <h2 style={{ fontSize: "1.05rem", margin: 0, color: "#f8fafc", fontWeight: "700" }}>Threat Severity Composition</h2>
            <span style={{ fontSize: "0.75rem", color: "#ff7b00", background: "rgba(255, 123, 0, 0.12)", border: "1px solid rgba(255, 123, 0, 0.35)", padding: "0.2rem 0.5rem", borderRadius: "4px" }}>AMBER ACCENT</span>
          </div>
          <SeverityPieChart alerts={alerts} />
        </div>
      </div>

      {/* Alerts Table with Multi-Facet Filters */}
      <div style={{
        background: "#060911",
        padding: "1.4rem",
        borderRadius: "10px",
        border: "1px solid rgba(0, 210, 255, 0.18)",
        boxShadow: "0 4px 20px rgba(0, 0, 0, 0.8)"
      }}>
        <div style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "space-between",
          alignItems: "center",
          gap: "1.2rem",
          marginBottom: "1.2rem",
          borderBottom: "1px solid rgba(0, 210, 255, 0.12)",
          paddingBottom: "1.2rem"
        }}>
          <div>
            <h2 style={{ fontSize: "1.1rem", margin: 0, color: "#f8fafc", fontWeight: "700" }}>Intrusion Stream & Mitigations</h2>
            <span style={{ fontSize: "0.8rem", color: "#718096" }}>
              Displaying <strong style={{ color: "#00d2ff" }}>{filteredAlerts.length}</strong> of {alerts.length} incident logs
            </span>
          </div>

          <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: "1rem" }}>
            {/* IP Address Search */}
            <div>
              <label style={{ marginRight: "0.5rem", fontSize: "0.8rem", color: "#90cdf4", fontWeight: "600", textTransform: "uppercase" }}>IP Filter:</label>
              <input
                type="text"
                placeholder="Search IP..."
                value={ipSearch}
                onChange={(e) => setIpSearch(e.target.value)}
                style={{
                  padding: "0.45rem 0.75rem",
                  borderRadius: "6px",
                  border: "1px solid rgba(0, 210, 255, 0.25)",
                  background: "#000000",
                  color: "#f8fafc",
                  fontSize: "0.85rem",
                  width: "160px",
                  outline: "none"
                }}
              />
            </div>

            {/* Type Filter */}
            <div>
              <label style={{ marginRight: "0.5rem", fontSize: "0.8rem", color: "#90cdf4", fontWeight: "600", textTransform: "uppercase" }}>Attack:</label>
              <select
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                style={{
                  padding: "0.45rem 0.75rem",
                  borderRadius: "6px",
                  border: "1px solid rgba(0, 210, 255, 0.25)",
                  background: "#000000",
                  color: "#f8fafc",
                  fontSize: "0.85rem",
                  outline: "none"
                }}
              >
                <option value="all">All Types</option>
                {alertTypes.map((t) => (
                  <option key={t} value={t}>
                    {t.replace("_", " ").toUpperCase()}
                  </option>
                ))}
              </select>
            </div>

            {/* Severity Filter */}
            <div>
              <label style={{ marginRight: "0.5rem", fontSize: "0.8rem", color: "#90cdf4", fontWeight: "600", textTransform: "uppercase" }}>Severity:</label>
              <select
                value={severityFilter}
                onChange={(e) => setSeverityFilter(e.target.value)}
                style={{
                  padding: "0.45rem 0.75rem",
                  borderRadius: "6px",
                  border: "1px solid rgba(0, 210, 255, 0.25)",
                  background: "#000000",
                  color: "#f8fafc",
                  fontSize: "0.85rem",
                  outline: "none"
                }}
              >
                <option value="all">All Severities</option>
                <option value="high">High</option>
                <option value="medium">Medium</option>
                <option value="low">Low</option>
              </select>
            </div>

            {/* Reset Button */}
            {(severityFilter !== "all" || typeFilter !== "all" || ipSearch) && (
              <button
                onClick={() => {
                  setSeverityFilter("all");
                  setTypeFilter("all");
                  setIpSearch("");
                }}
                style={{
                  padding: "0.45rem 0.85rem",
                  background: "rgba(255, 123, 0, 0.15)",
                  border: "1px solid rgba(255, 123, 0, 0.45)",
                  borderRadius: "6px",
                  fontSize: "0.8rem",
                  cursor: "pointer",
                  color: "#ff7b00",
                  fontWeight: "700",
                }}
              >
                Reset Filters
              </button>
            )}
          </div>
        </div>
        <AlertsTable
          alerts={filteredAlerts}
          blockedIPs={blockedIPs}
          onBlockIP={handleBlockIP}
          onUnblockIP={handleUnblockIP}
        />
      </div>
    </div>
  );
}
